/**
 * Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty object. Note that you should only return the payload of the decoded thing.
 *
 * @param {string} token - The JWT token to decode.
 * @param {string} key - The key used in encoding.
 * @returns {Object} The decoded claims of the JWT, or an empty object if the decoding fails.
 */
function decodeJsonWebToken(token, key) {
  try {
    // The jwt.verify function returns the decoded payload if verification is successful.
    // It throws an error if the token is invalid, expired, or the signature doesn't match.
    // The 'payload' property is not directly available on the decoded object from jwt.verify.
    // jwt.verify itself returns the payload.
    const decodedPayload = jwt.verify(token, key, { algorithms: ['HS256'] });
    return decodedPayload;
  } catch (error) {
    // If any error occurs during verification, return an empty object as per the requirement.
    return {};
  }
}
